import Foundation

/// The settings of a freshly imported, unedited variant, for `get` with `changed: true`.
/// Generated by `scripts/v2-defaults.py`; fields listed in `alwaysReported` depend on the camera,
/// lens or image, so they are reported without comparison.
public struct Defaults: Decodable {
    public let alwaysReported: [String: [String]]
    public let defaults: [String: [String: JSONValue]]

    public static func bundled() throws -> Defaults {
        guard let url = Bundle.module.url(forResource: "Defaults", withExtension: "json"),
              let data = try? Data(contentsOf: url) else {
            throw C1Failure(.internal, "Defaults.json is missing from the C1Kit bundle.")
        }
        return try JSONDecoder().decode(Defaults.self, from: data)
    }

    public init(alwaysReported: [String: [String]], defaults: [String: [String: JSONValue]]) {
        self.alwaysReported = alwaysReported; self.defaults = defaults
    }

    /// Keeps the fields that are always reported, unknown to the defaults, or different from them.
    func changed(_ fields: [String: JSONValue], section: String, baseline: [String: JSONValue]? = nil) -> [String: JSONValue] {
        let always = Set(alwaysReported[section] ?? [])
        let reference = defaults[section] ?? [:]
        return fields.filter { name, value in
            if always.contains(name) {
                guard let baseline else { return true }
                return baseline[name].map { !value.approximatelyEquals($0) } ?? true
            }
            return reference[name].map { !value.approximatelyEquals($0) } ?? true
        }
    }

    /// Non-background layers compare camera-dependent adjustments against the Image layer's values.
    public func changed(_ state: VariantState) -> JSONValue {
        let layers = state.layers.map { layer -> JSONValue in
            var kept = changed(layer.filter { $0.key != "adjustments" }, section: "layer")
            if case .object(let adjustments)? = layer["adjustments"] {
                kept["adjustments"] = .object(changed(adjustments, section: "adjustments", baseline: state.adjustments))
            }
            return .object(kept)
        }
        return .object([
            "id": .string(state.id.description),
            "variant": .object(changed(state.variant, section: "variant")),
            "adjustments": .object(changed(state.adjustments, section: "adjustments")),
            "lensCorrection": .object(changed(state.lensCorrection, section: "lensCorrection")),
            "layers": .array(layers),
        ])
    }
}
